eSpellings":["Capestang","Béziers","Beziers","Agde","Sete","Sète"],"canalReach":"Canal du Midi, Orb/Hérault works, and Étang de Thau approach","keyPlaces":["Tunnel de Malpas","Neuf écluses de Fonseranes","Béziers","Agde écluse ronde","Marseillan plage","Sète"],"officialStageUrl":"https://www.canaldes2mersavelo.com/itineraire/le-canal-du-midi-a-velo-agde-sete","franceVeloUrl":"https://www.francevelotourisme.com/itineraire/le-canal-des-2-mers-a-velo/agde-sete"}];
return [{ json: { segments, contextGeneratedAt: new Date().toISOString(), contextSource: 'data/route-monitoring/route-geography-crosswalk.json' } }];

const config = $items('Set Connector Config')[0].json;
const startUrls = [
  'https://www.vnf.fr/vnf/avis-a-la-batellerie/',
  'https://www.vnf.fr/vnf/publicationss/avis-a-la-batellerie-n1-2025-vnf-sud-ouest/',
  'https://www.vnf.fr/vnf/services/avis-a-la-batellerie-n1-des-voies-du-sud-ouest/',
  'https://www.vnf.fr/vnf/wp-json/wp/v2/search?search=avis%20batellerie%20sud-ouest&per_page=20',
];
const sourcePageUrl = 'https://www.vnf.fr/vnf/publicationss/avis-a-la-batellerie-n1-2025-vnf-sud-ouest/';
const targetYear = '2026';
return [{ json: { startUrls, sourcePageUrl, targetYear, generatedAt: config.generatedAt } }];

// Faithful adaptation of scripts/route-monitoring/fetch-vnf.mjs's discoverLiveDocuments(). Runs
// entirely inside one Code node (runOnceForAllItems) using this.helpers.httpRequest because the
// real VNF discovery flow spans 4 listing/search URLs plus follow-up URLs resolved from a WordPress
// search JSON response - a shape n8n's single-endpoint HTTP Request node cannot express directly.
const requestConfig = $items('Build VNF Request Config')[0].json;
const { startUrls, targetYear } = requestConfig;
const checkedAt = new Date().toISOString();
const errors = [];
let pagesFetched = 0;

function decodeEntities(value) {
  return String(value || '')
    .replace(/&#(\d+);/g, (_, code) => String.fromCharCode(Number(code)))
    .replace(/&#x([0-9a-f]+);/gi, (_, code) => String.fromCharCode(parseInt(code, 16)))
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&rsquo;|&#8217;/g, "'")
    .replace(/&eacute;/g, 'é')
    .replace(/&egrave;/g, 'è')
    .replace(/&agrave;/g, 'à')
    .replace(/&ecirc;/g, 'ê')
    .replace(/&ccedil;/g, 'ç');
}
function htmlToText(html) {
  return decodeEntities(html)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function extractLinks(html, baseUrl) {
  const links = [];
  for (const match of html.matchAll(/(?:href|src)=["']([^"']+)["']/gi)) {
    try {
      links.push(new URL(decodeEntities(match[1]), baseUrl).href);
    } catch (err) {
      // Ignore malformed page fragments.
    }
  }
  return links;
}
function extractUrlsFromSearchJson(text) {
  try {
    const rows = JSON.parse(text);
    return Array.isArray(rows)
      ? rows
        .filter((row) => String(row.title || '').toLowerCase().includes(targetYear) || String(row.url || '').includes('n1-2025-vnf-sud-ouest'))
        .map((row) => row.url)
        .filter(Boolean)
      : [];
  } catch (err) {
    return [];
  }
}

async function fetchText(url) {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url,
    timeout: 25000,
    returnFullResponse: true,
    headers: {
      'User-Agent': 'BikeTourFrance-CDM-RouteMonitor/0.1 (+https://biketourfrance.net; route status research)',
      Accept: 'text/html,application/xhtml+xml,application/xml,text/plain,application/json;q=0.9,*/*;q=0.8',
    },
  });
  return { url: response.url || url, text: typeof response.body === 'string' ? response.body : JSON.stringify(response.body) };
}

const pages = new Map();
for (const url of startUrls) {
  try {
    const fetched = await fetchText.call(this, url);
    pages.set(fetched.url, fetched.text);
    pagesFetched += 1;
    if (url.includes('/wp-json/')) {
      for (const resultUrl of extractUrlsFromSearchJson(fetched.text)) {
        if (/avis-a-la-batellerie/i.test(resultUrl) && !pages.has(resultUrl)) {
          try {
            const resultPage = await fetchText.call(this, resultUrl);
            pages.set(resultPage.url, resultPage.text);
            pagesFetched += 1;
          } catch (err) {
            errors.push('fetch ' + resultUrl + ': ' + err.message);
          }
        }
      }
    }
  } catch (err) {
    errors.push('fetch ' + url + ': ' + err.message);
  }
}

const documents = new Map();
for (const [pageUrl, html] of pages) {
  const pageText = htmlToText(html);
  const targetYearPage = pageText.includes(targetYear) || pageUrl.includes('n1-2025-vnf-sud-ouest');
  for (const link of extractLinks(html, pageUrl)) {
    if (
      /\.pdf(?:$|\?)/i.test(link)
      && /AvisBat|Avis|Batellerie|Sud-ouest|Sud-Ouest/i.test(link)
      && (link.includes(targetYear) || targetYearPage)
    ) {
      documents.set(link, { pdfUrl: link, sourceUrl: pageUrl });
    }
  }
}

const fetchMeta = {
  recordKind: 'fetchMeta',
  fetchOk: pagesFetched > 0,
  pagesFetched,
  pdfCandidateCount: documents.size,
  errors,
  checkedAt,
};

return [
  { json: fetchMeta },
  ...[...documents.values()].map((doc) => ({ json: { recordKind: 'pdfCandidate', ...doc, checkedAt } })),
];

// Faithful adaptation of scripts/route-monitoring/fetch-vnf.mjs's parseNoticesFromText /
// parseChomageNotices / parseAvisBlocks. Runs after n8n-nodes-base.extractFromFile (pdf operation)
// has already turned each fetched PDF into plain text - the extractFromFile node is used instead of
// a hand-rolled Code-node PDF parser because the live VNF PDFs use compressed (FlateDecode) content
// streams; a pure-regex parser with no zlib/pdf-parse access (n8n's Code sandbox disallows
// require('zlib') the same way it disallows require('fs')/require('crypto')) returns 0 characters on
// the real document (confirmed empirically during source-shape probing), so PDF decompression must be
// done by n8n's native, non-sandboxed Extract From File node.
const extractedItems = $input.all();
const candidateItems = $items('Filter PDF Candidates'); // aligned 1:1 by index with the PDF-fetch branch
const effectRegex = /(arr[êe]t de navigation|navigation interrompue|ch[oô]mage|fermeture|restriction|alternat|travaux|chantier|interdit|d[eé]viation)/i;
const corridorRegex = /(canal du midi|canal lat[ée]ral [àa] la garonne|canal de garonne|moissac|agen|castelsarrasin|montech|toulouse|castelnaudary|carcassonne|tr[èe]bes|homps|capestang|b[ée]ziers|agde|s[èe]te)/i;

function normalize(value) {
  return String(value || '')
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase();
}
function simpleHash(value) {
  let hash = 0;
  const s = String(value || '');
  for (let i = 0; i < s.length; i += 1) hash = (Math.imul(31, hash) + s.charCodeAt(i)) | 0;
  return (hash >>> 0).toString(16).padStart(8, '0');
}
function cleanNoticeText(text) {
  return String(text || '')
    .replace(/\f/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}
function parseFrenchDate(value) {
  const months = { janvier: '01', fevrier: '02', 'février': '02', mars: '03', avril: '04', mai: '05', juin: '06', juillet: '07', aout: '08', 'août': '08', septembre: '09', octobre: '10', novembre: '11', decembre: '12', 'décembre': '12' };
  const match = String(value || '').toLowerCase().match(/(\d{1,2})\s+([a-zéû]+)\s+(20\d{2})/i);
  if (!match) return null;
  const month = months[match[2]];
  if (!month) return null;
  return match[3] + '-' + month + '-' + String(Number(match[1])).padStart(2, '0');
}
function dateRangeFromText(text) {
  const dates = [...String(text || '').matchAll(/(\d{1,2}\s+(?:janvier|f[ée]vrier|mars|avril|mai|juin|juillet|ao[ûu]t|septembre|octobre|novembre|d[ée]cembre)\s+20\d{2})/gi)]
    .map((m) => parseFrenchDate(m[1]))
    .filter(Boolean);
  return { startedAt: dates[0] || null, endedAt: dates[1] || null };
}
function extractWaterway(text) {
  const match = String(text || '').match(/(Canal (?:lat[ée]ral [àa] la Garonne|de Garonne|du Midi|de Montech [àa] Montauban|de Brienne|de Jonction|de la Robine)|Fleuve Garonne|Rivi[èe]re Ba[ïi]se)/i);
  return match ? match[1] : 'VNF Sud-Ouest';
}
function extractEffect(text) {
  const lower = String(text || '').toLowerCase();
  if (/chemin de halage|acc[èe]s public|cycliste|piste cyclable|voie verte|pi[ée]ton|passerelle/.test(lower)) return "Restriction d'accès au chemin de halage ou au public";
  if (/ch[oô]mage|arr[êe]t de navigation|navigation interrompue/.test(lower)) return 'Arrêt de navigation';
  if (/alternat/.test(lower)) return 'Alternat de navigation';
  if (/restriction/.test(lower)) return 'Restriction de navigation';
  if (/travaux|chantier/.test(lower)) return 'Travaux';
  return 'Avis à la batellerie';
}
function parseChomageNotices(text) {
  if (!/p[ée]riodes? pour les travaux de ch[oô]mage/i.test(text)) return [];
  const noticeText = text.replace(/\f/g, '\n');
  const midiMatch = noticeText.match(/Canal du Midi[\s\S]{0,900}?ch[oô]mage[\s\S]{0,600}?Navigation interrompue/i);
  const garonneMatch = noticeText.match(/Canal lat[ée]ral [àa] la Garonne[\s\S]{0,900}?ch[oô]mage[\s\S]{0,600}?Navigation interrompue/i);
  const notices = [];
  if (midiMatch) {
    const dates = dateRangeFromText(midiMatch[0]);
    notices.push({ noticeNumber: 'chomage-midi-' + simpleHash(midiMatch[0]).slice(0, 6), waterway: 'Canal du Midi', title: 'VNF Sud-Ouest: chômage du Canal du Midi', effect: 'Arrêt de navigation pendant la période de chômage', startedAt: dates.startedAt, endedAt: dates.endedAt, evidenceText: midiMatch[0] });
  }
  if (garonneMatch) {
    const dates = dateRangeFromText(garonneMatch[0]);
    notices.push({ noticeNumber: 'chomage-garonne-' + simpleHash(garonneMatch[0]).slice(0, 6), waterway: 'Canal latéral à la Garonne', title: 'VNF Sud-Ouest: chômage du Canal latéral à la Garonne', effect: 'Arrêt de navigation pendant la période de chômage', startedAt: dates.startedAt, endedAt: dates.endedAt, evidenceText: garonneMatch[0] });
  }
  return notices;
}
function parseAvisBlocks(text) {
  const normalized = cleanNoticeText(text);
  const starts = [...normalized.matchAll(/AVIS\s+[ÀA]\s+LA\s+BATELLERIE\s+N[°º]\s*[^\n]*/gi)].map((m) => m.index);
  if (!starts.length) return [];
  const blocks = [];
  for (let i = 0; i < starts.length; i += 1) {
    const start = starts[i];
    const end = starts[i + 1] !== undefined ? starts[i + 1] : normalized.length;
    const block = normalized.slice(start, end).trim();
    if (effectRegex.test(block) && corridorRegex.test(block)) blocks.push(block);
  }
  return blocks.map((block) => {
    const lines = block.split(/\n+/).map((l) => l.trim()).filter(Boolean);
    const firstLine = lines[0] || 'Avis à la batellerie VNF';
    const number = (firstLine.match(/N[°º]\s*([^\s]+)/i) || [])[1] || simpleHash(block).slice(0, 8);
    const waterway = extractWaterway(block);
    const dates = dateRangeFromText(block);
    return { noticeNumber: number, waterway, title: lines[1] ? (firstLine + ': ' + lines[1]) : firstLine, effect: extractEffect(block), startedAt: dates.startedAt, endedAt: dates.endedAt, evidenceText: block };
  });
}
function parseNoticesFromText(text) {
  const chomage = parseChomageNotices(text);
  const blocks = parseAvisBlocks(text);
  const all = [...chomage, ...blocks];
  const seen = new Set();
  return all.filter((notice) => {
    const key = normalize(notice.noticeNumber + ' ' + notice.title + ' ' + notice.evidenceText.slice(0, 120));
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

const parsedNotices = [];
const docErrors = [];
let documentsProcessed = 0;

for (let i = 0; i < extractedItems.length; i += 1) {
  const item = extractedItems[i];
  const meta = (candidateItems[i] && candidateItems[i].json) || {};
  if (item.json && item.json.error) {
    docErrors.push('document ' + (meta.pdfUrl || 'unknown') + ': ' + item.json.error);
    continue;
  }
  const text = (item.json && (item.json.text || item.json.data)) || '';
  if (!text || String(text).trim().length < 50) {
    docErrors.push('document ' + (meta.pdfUrl || 'unknown') + ': extraction produced no usable text (extractFromFile returned ' + String(text).length + ' chars)');
    continue;
  }
  documentsProcessed += 1;
  const notices = parseNoticesFromText(String(text));
  for (const notice of notices) {
    if (!corridorRegex.test(notice.waterway + ' ' + notice.title + ' ' + notice.evidenceText)) continue;
    parsedNotices.push({
      recordKind: 'parsedNotice',
      noticeNumber: notice.noticeNumber,
      waterway: notice.waterway,
      title: notice.title.slice(0, 180),
      effect: notice.effect,
      startedAt: notice.startedAt,
      endedAt: notice.endedAt,
      evidenceText: cleanNoticeText(notice.evidenceText).slice(0, 1200),
      evidenceUrl: meta.pdfUrl || 'unknown',
      sourceUrl: meta.sourceUrl || 'unknown',
      extractionMethod: 'extractFromFile_pdf',
    });
  }
}

const seenGlobal = new Set();
const dedupedNotices = parsedNotices.filter((n) => {
  const key = normalize(n.evidenceUrl + ' ' + n.title + ' ' + n.evidenceText.slice(0, 100));
  if (seenGlobal.has(key)) return false;
  seenGlobal.add(key);
  return true;
});

const parseMeta = {
  recordKind: 'parseMeta',
  documentsSeen: extractedItems.length,
  documentsProcessed,
  documentErrors: docErrors,
  noticeCount: dedupedNotices.length,
  checkedAt: new Date().toISOString(),
};

return [{ json: parseMeta }, ...dedupedNotices.map((n) => ({ json: n }))];

// Classifies each parsedNotice into an official VNF notice-type category. Never classifies any
// category as a route/bike closure - official canal/waterway status stays official canal/waterway
// status (per the CDM canal/flood/route-impact separation rule).
const items = $input.all().map((i) => i.json || {});
function classify(notice) {
  const text = (notice.title + ' ' + notice.effect + ' ' + notice.evidenceText).toLowerCase();
  if (/p[ée]riodes? pour les travaux de ch[oô]mage|ch[oô]mage/.test(text)) return { officialNoticeType: 'chomage_calendar', officialCanalStatus: 'scheduled_maintenance_closure' };
  if (/[ée]cluse/.test(text) && /ferm/.test(text)) return { officialNoticeType: 'lock_closure', officialCanalStatus: 'lock_closed' };
  if (/arr[êe]t de navigation|navigation interrompue/.test(text)) return { officialNoticeType: 'waterway_closure', officialCanalStatus: 'navigation_stopped' };
  if (/restriction|alternat/.test(text)) return { officialNoticeType: 'navigation_restriction', officialCanalStatus: 'navigation_restricted' };
  if (/travaux|chantier/.test(text)) return { officialNoticeType: 'canal_maintenance', officialCanalStatus: 'maintenance_in_progress' };
  if (notice.recordKind === 'parsedNotice') return { officialNoticeType: 'informational_notice', officialCanalStatus: 'notice_published' };
  return null;
}
return items.map((item) => {
  if (item.recordKind !== 'parsedNotice') return { json: item };
  const c = classify(item) || { officialNoticeType: 'unknown_notice_type', officialCanalStatus: 'unspecified' };
  return { json: { ...item, ...c } };
});

// Detects EXPLICIT official route/towpath/public-access impact per the strict CDM domain-boundary
// rule: canal/navigation status alone (open/closed/restricted/maintenance/chômage) is never route
// status. routeImpactStatus only becomes "reported" when the evidence text contains BOTH a
// towpath/cycling-infrastructure term AND an explicit closure/impact verb applied to it - a
// deliberately stricter combined check than the repo's single-term vnfCyclistText() gate (which only
// requires a towpath/cycling mention and is used for auto_publish ELIGIBILITY, not for asserting
// confirmed route impact). Mere mention of "halage" or "piste cyclable" in a boat-navigation notice
// is NOT sufficient on its own to set routeImpactStatus="reported".
const items = $input.all().map((i) => i.json || {});
const towpathTerm = /(chemin de halage|voie verte|piste cyclable|itin[ée]raire v[ée]lo|route cyclable|acc[èe]s public)/i;
const closureVerb = /(ferm[ée]e?s?|interdit|interrompu|coup[ée]e?s?|barr[ée]e?s?)/i;
const explicitPhrases = [
  /chemin de halage ferm/i,
  /voie verte ferm/i,
  /piste cyclable ferm/i,
  /itin[ée]raire v[ée]lo ferm/i,
  /acc[èe]s public interdit/i,
  /d[ée]viation cyclable/i,
  /fermeture du chemin/i,
  /interruption de l.?itin[ée]raire/i,
  /route cyclable impact[ée]e/i,
];
function detect(evidenceText) {
  const text = String(evidenceText || '');
  const explicit = explicitPhrases.some((re) => re.test(text));
  const combined = towpathTerm.test(text) && closureVerb.test(text);
  const cyclistMentioned = /(chemin de halage|halage|voie verte|piste cyclable|cyclable|cycliste|v[ée]lo|acc[èe]s public|pi[ée]ton|passerelle)/i.test(text);
  const hasExplicitImpact = explicit || combined;
  return {
    routeImpactStatus: hasExplicitImpact ? 'reported' : 'not_indicated',
    routeClosureConfirmed: false,
    towpathClosureConfirmed: hasExplicitImpact && /chemin de halage|halage/i.test(text),
    publicAccessClosureConfirmed: hasExplicitImpact && /acc[èe]s public/i.test(text),
    detourConfirmed: hasExplicitImpact && /d[ée]viation/i.test(text),
    hasCyclistTowpathMention: cyclistMentioned,
  };
}
return items.map((item) => {
  if (item.recordKind !== 'parsedNotice') return { json: item };
  return { json: { ...item, ...detect(item.evidenceText) } };
});

// Adapted from scripts/route-monitoring/fetch-vnf.mjs's mapLocation()/canalInterval(), using the
// segment list embedded in "Load / Embed Canal Route Context" (real repo data - never invented).
// Because each crosswalk segment already carries its own rideDay, route-day mapping is derived
// directly from matched-segment overlap instead of needing the full route geometry file.
const contextItems = $items('Load / Embed Canal Route Context');
const segments = (contextItems[0] && contextItems[0].json.segments) || [];
const items = $input.all().map((i) => i.json || {});
const kmToMiFactor = 0.621371;

function normalize(value) {
  return String(value || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[’']/g, ' ').replace(/[^a-z0-9]+/g, ' ').trim();
}
function canalInterval(text) {
  const n = normalize(text);
  if (/(canal de garonne|canal lateral a la garonne)/.test(n)) {
    return { label: 'Canal latéral à la Garonne', matched: segments.filter((s) => /canal lateral a la garonne/.test(normalize(s.canalReach))) };
  }
  if (/canal du midi/.test(n)) {
    return { label: 'Canal du Midi', matched: segments.filter((s) => normalize(s.canalReach).includes('canal du midi')) };
  }
  return null;
}
function mapLocation(text) {
  const normalized = normalize(text);
  const terms = [];
  for (const segment of segments) {
    const names = [segment.segmentId, segment.startTown, segment.endTown, ...(segment.keyPlaces || []), ...(segment.alternateSpellings || [])];
    for (const name of names) if (name) terms.push({ term: normalize(name), label: name, segment });
  }
  terms.sort((a, b) => b.term.length - a.term.length);
  for (const entry of terms) {
    if (entry.term.length >= 4 && normalized.includes(entry.term)) return locationFromSegments([entry.segment], entry.label);
  }
  const broad = canalInterval(text);
  if (broad && broad.matched.length) return locationFromSegments(broad.matched, broad.label);
  return { routeRelation: 'unknown_location', confidence: 'unknown', locationText: 'VNF Sud-Ouest waterway, exact CDM route relation unmapped', department: 'unknown', rdStart: null, rdEnd: null, tourDayIds: [] };
}
function locationFromSegments(matched, label) {
  const sorted = [...matched].sort((a, b) => a.kmStart - b.kmStart);
  const kmStart = sorted[0].kmStart;
  const kmEnd = sorted[sorted.length - 1].kmEnd;
  const rideDays = [...new Set(sorted.map((s) => s.rideDay))].sort((a, b) => a - b);
  const tourDayIds = rideDays.map((d) => 'RD0' + d);
  const departments = [...new Set(sorted.flatMap((s) => s.departments || []))];
  return {
    routeRelation: 'on_route',
    confidence: sorted.length > 1 ? 'medium' : 'high',
    locationText: label,
    department: departments.join('/') || 'unknown',
    routeKmStart: Number(kmStart.toFixed(3)),
    routeKmEnd: Number(kmEnd.toFixed(3)),
    routeMpStart: Number((kmStart * kmToMiFactor).toFixed(1)),
    routeMpEnd: Number((kmEnd * kmToMiFactor).toFixed(1)),
    rdStart: rideDays[0] || null,
    rdEnd: rideDays[rideDays.length - 1] || null,
    tourDayIds,
  };
}

return items.map((item) => {
  if (item.recordKind !== 'parsedNotice') return { json: item };
  const location = mapLocation(item.waterway + '\n' + item.title + '\n' + item.evidenceText);
  const mappingConfidence = location.confidence === 'unknown' ? 'unknown' : location.confidence;
  let reviewState;
  if (mappingConfidence === 'unknown' || location.routeRelation === 'unknown_location') {
    reviewState = 'manual_review_required';
  } else if (item.routeImpactStatus === 'reported' && location.rdStart) {
    reviewState = 'auto_publish_candidate';
  } else if (item.routeImpactStatus === 'not_indicated') {
    reviewState = 'informational';
  } else {
    reviewState = 'manual_review_required';
  }
  return { json: { ...item, ...location, mappingConfidence, reviewState } };
});

