    parsed = JSON.parse(text);
  } catch (err) {
    results.push({ json: { label, targetPath, validJson: false, bytes: Buffer.byteLength(text, 'utf8'), error: 'Invalid JSON: ' + err.message } });
    continue;
  }
  let shapeError = null;
  if (label === 'canal-status-connector-output' && (!parsed.connectorId || !Array.isArray(parsed.sourceHealth) || !parsed.validation)) {
    shapeError = 'canal-status-connector-output missing connectorId, sourceHealth[], or validation';
  }
  if (label === 'canal-source-health' && !Array.isArray(parsed.sources)) {
    shapeError = 'canal-source-health missing sources[]';
  }
  if (!LABELS.has(label)) shapeError = shapeError || ('Unexpected output label: ' + label);
  results.push({ json: { label, targetPath, validJson: !shapeError, bytes: Buffer.byteLength(text, 'utf8'), error: shapeError } });
}
return results;

const config = $items('Set Connector Config')[0].json;
const validationResults = $input.all().map((i) => i.json || {});
const generatedAt = config.generatedAt || new Date().toISOString();
const completedAt = new Date().toISOString();
const failures = validationResults.filter((r) => r.validJson !== true || r.error);
const errors = failures.map((f) => ({ label: f.label, targetPath: f.targetPath, message: f.error || 'Output file did not pass validation' }));

const normalizeItems = $items('Normalize Canal Status Records').map((i) => i.json);
const officialCanalNoticeCount = normalizeItems.length;
const navigationRestrictionCount = normalizeItems.filter((n) => n.officialNoticeType === 'navigation_restriction').length;
const maintenanceChomageCount = normalizeItems.filter((n) => ['canal_maintenance', 'chomage_calendar'].includes(n.officialNoticeType)).length;
const routeImpactConfirmedCount = normalizeItems.filter((n) => n.routeImpactStatus === 'reported').length;
const manualReviewCount = normalizeItems.filter((n) => n.reviewState === 'manual_review_required').length;
const autoPublishCandidateCount = normalizeItems.filter((n) => n.reviewState === 'auto_publish_candidate').length;

const healthItems = $items('Build Source Health').map((i) => i.json);
const sourceApiBlocked = healthItems.some((h) => h.status === 'source_api_blocked');
const sourceShapeChanged = healthItems.some((h) => h.status === 'source_shape_changed');
const fetchMetaItems = $items('Fetch VNF Source Index / Notices').map((i) => i.json).filter((i) => i.recordKind === 'fetchMeta');
const parseMetaItems = $items('Parse VNF Notices').map((i) => i.json).filter((i) => i.recordKind === 'parseMeta');
const ignoredCount = (parseMetaItems[0] && (parseMetaItems[0].documentErrors || []).length) || 0;

return [{
  json: {
    recordKind: 'runDiagnostics',
    ok: errors.length === 0,
    connectorId: config.connectorId,
    workflowName: config.workflowName,
    workflowVersion: config.workflowVersion,
    generatedAt,
    completedAt,
    validationStatus: errors.length === 0 ? 'passed' : 'failed',
    sourceStatus: sourceApiBlocked ? 'source_api_blocked' : sourceShapeChanged ? 'source_shape_changed' : 'ok',
    writeStatus: validationResults.length > 0 ? 'attempted' : 'not_attempted',
    infraBlocked: false,
    fileAccessRegression: false,
    sourceApiBlocked,
    sourceShapeChanged,
    outputFilenames: validationResults.map((r) => r.targetPath).filter(Boolean),
    officialCanalNoticeCount,
    navigationRestrictionCount,
    maintenanceChomageCount,
    ignoredCount,
    routeImpactConfirmedCount,
    manualReviewCount,
    autoPublishCandidateCount,
    errors,
    warnings: [],
    nextAction: errors.length === 0 ? 'Owner to move workflow into CDM_Status_Seven_Connectors folder' : 'Debug failing node before folder move',
    folderMoveRequired: true,
  },
}];
